#!/usr/bin/env bun

import { readFileSync, readdirSync, statSync } from 'fs';
import { join } from 'path';

interface FileAnalysis {
  filename: string;
  sizeBytes: number;
  sizeMB: number;
  resourceCounts: Record<string, number>;
  totalResources: number;
  patientBirthDate?: string;
  patientGender?: string;
  patientName?: string;
  conditionCount: number;
  conditions: string[];
  dateRange?: {
    earliest: string;
    latest: string;
  };
  hasComplexConditions: boolean;
}

const DATA_DIR = '/Users/hrishioa/Dropbox/Projects/Southbridge/experiments/sealed-agents/tests/healthcare-ehr-langton/data/fhir';

function analyzeFile(filename: string): FileAnalysis {
  const filePath = join(DATA_DIR, filename);
  const stats = statSync(filePath);
  const content = readFileSync(filePath, 'utf8');

  let data: any;
  try {
    data = JSON.parse(content);
  } catch (e) {
    console.error(`Failed to parse ${filename}:`, e);
    return {
      filename,
      sizeBytes: stats.size,
      sizeMB: stats.size / (1024 * 1024),
      resourceCounts: {},
      totalResources: 0,
      conditionCount: 0,
      conditions: [],
      hasComplexConditions: false
    };
  }

  // Count resources by type
  const resourceCounts: Record<string, number> = {};
  let totalResources = 0;
  let patientBirthDate: string | undefined;
  let patientGender: string | undefined;
  let patientName: string | undefined;
  const conditions: string[] = [];
  const dates: string[] = [];

  if (data.entry) {
    for (const entry of data.entry) {
      if (entry.resource?.resourceType) {
        const resourceType = entry.resource.resourceType;
        resourceCounts[resourceType] = (resourceCounts[resourceType] || 0) + 1;
        totalResources++;

        // Extract patient info
        if (resourceType === 'Patient') {
          patientBirthDate = entry.resource.birthDate;
          patientGender = entry.resource.gender;
          if (entry.resource.name?.[0]) {
            const name = entry.resource.name[0];
            patientName = `${name.given?.[0]} ${name.family}`;
          }
        }

        // Extract conditions
        if (resourceType === 'Condition') {
          const display = entry.resource.code?.coding?.[0]?.display;
          if (display) {
            conditions.push(display);
          }
        }

        // Extract dates
        if (entry.resource.effectiveDateTime) {
          dates.push(entry.resource.effectiveDateTime);
        }
      }
    }
  }

  // Check for complex conditions
  const complexConditionKeywords = [
    'diabetes', 'hypertension', 'heart disease', 'kidney disease', 
    'cancer', 'stroke', 'myocardial infarction', 'chronic obstructive'
  ];

  const hasComplexConditions = conditions.some(condition => 
    complexConditionKeywords.some(keyword => 
      condition.toLowerCase().includes(keyword)
    )
  );

  // Calculate date range
  let dateRange: { earliest: string; latest: string } | undefined;
  if (dates.length > 0) {
    const sortedDates = dates.sort();
    dateRange = {
      earliest: sortedDates[0],
      latest: sortedDates[sortedDates.length - 1]
    };
  }

  return {
    filename,
    sizeBytes: stats.size,
    sizeMB: stats.size / (1024 * 1024),
    resourceCounts,
    totalResources,
    patientBirthDate,
    patientGender,
    patientName,
    conditionCount: conditions.length,
    conditions,
    dateRange,
    hasComplexConditions
  };
}

function main() {
  console.log('🔍 Analyzing FHIR files...\n');

  const files = readdirSync(DATA_DIR).filter(f => f.endsWith('.json'));
  console.log(`Found ${files.length} JSON files\n`);

  // Analyze a sample of files (small, medium, large)
  const sampleFiles = [
    // Small files
    ...files.filter(f => statSync(join(DATA_DIR, f)).size < 10 * 1024 * 1024).slice(0, 5),
    // Medium files  
    ...files.filter(f => {
      const size = statSync(join(DATA_DIR, f)).size;
      return size >= 10 * 1024 * 1024 && size < 30 * 1024 * 1024;
    }).slice(0, 5),
    // Large files
    ...files.filter(f => statSync(join(DATA_DIR, f)).size >= 30 * 1024 * 1024).slice(0, 5)
  ];

  console.log(`Analyzing ${sampleFiles.length} sample files:\n`);

  const analyses: FileAnalysis[] = [];

  for (const filename of sampleFiles) {
    console.log(`📊 Analyzing ${filename}...`);
    const analysis = analyzeFile(filename);
    analyses.push(analysis);

    console.log(`   Size: ${analysis.sizeMB.toFixed(1)}MB`);
    console.log(`   Resources: ${analysis.totalResources}`);
    console.log(`   Conditions: ${analysis.conditionCount}`);
    console.log(`   Complex conditions: ${analysis.hasComplexConditions ? 'Yes' : 'No'}`);
    console.log(`   Date range: ${analysis.dateRange?.earliest} to ${analysis.dateRange?.latest}`);
    console.log('');
  }

  // Summary statistics
  console.log('\n📈 SUMMARY STATISTICS:\n');

  const avgSize = analyses.reduce((sum, a) => sum + a.sizeMB, 0) / analyses.length;
  const avgResources = analyses.reduce((sum, a) => sum + a.totalResources, 0) / analyses.length;
  const avgConditions = analyses.reduce((sum, a) => sum + a.conditionCount, 0) / analyses.length;
  const complexConditionCount = analyses.filter(a => a.hasComplexConditions).length;

  console.log(`Average file size: ${avgSize.toFixed(1)}MB`);
  console.log(`Average resources: ${avgResources.toFixed(0)}`);
  console.log(`Average conditions: ${avgConditions.toFixed(0)}`);
  console.log(`Files with complex conditions: ${complexConditionCount}/${analyses.length} (${(complexConditionCount/analyses.length*100).toFixed(1)}%)`);

  // Resource type distribution
  console.log('\n🏥 RESOURCE TYPE DISTRIBUTION:\n');
  const resourceTypeSums: Record<string, number> = {};

  for (const analysis of analyses) {
    for (const [resourceType, count] of Object.entries(analysis.resourceCounts)) {
      resourceTypeSums[resourceType] = (resourceTypeSums[resourceType] || 0) + count;
    }
  }

  const sortedResourceTypes = Object.entries(resourceTypeSums)
    .sort(([,a], [,b]) => b - a)
    .slice(0, 10);

  for (const [resourceType, totalCount] of sortedResourceTypes) {
    const avgCount = totalCount / analyses.length;
    console.log(`${resourceType}: ${totalCount} total (avg ${avgCount.toFixed(1)} per file)`);
  }

  // Correlation analysis
  console.log('\n🔗 CORRELATION ANALYSIS:\n');

  const sizeComplexCorrelation = analyses.filter(a => a.hasComplexConditions).length > 0;
  console.log(`Files with complex conditions tend to be larger: ${sizeComplexCorrelation}`);

  // Check if observation count correlates with file size
  const observationSizeCorrelation = analyses.map(a => ({
    size: a.sizeMB,
    observations: a.resourceCounts['Observation'] || 0
  }));

  console.log('\nObservation count vs file size:');
  for (const { size, observations } of observationSizeCorrelation.slice(0, 10)) {
    console.log(`  ${size.toFixed(1)}MB: ${observations} observations`);
  }

  console.log('\n✅ Analysis complete!');
}

if (import.meta.main) {
  main();
}

#!/usr/bin/env bun

import { readFileSync } from 'fs';

// Let's examine the Shayne60 file that has the 1918-2025 date range
const filename = '/Users/hrishioa/Dropbox/Projects/Southbridge/experiments/sealed-agents/tests/healthcare-ehr-langton/data/fhir/Shayne60_Schaden604_7ab86df8-7953-390e-6a42-0c8b63002fda.json';

function investigateDateAnomaly() {
  console.log('🔍 Investigating date range anomaly...\n');

  const content = readFileSync(filename, 'utf8');
  const data = JSON.parse(content);

  // Find patient info
  const patientEntry = data.entry.find((entry: any) => entry.resource?.resourceType === 'Patient');
  if (patientEntry) {
    console.log('👤 Patient Information:');
    console.log(`   Name: ${patientEntry.resource.name?.[0]?.given?.[0]} ${patientEntry.resource.name?.[0]?.family}`);
    console.log(`   Birth Date: ${patientEntry.resource.birthDate}`);
    console.log(`   Gender: ${patientEntry.resource.gender}`);
    console.log('');
  }

  // Collect all dates
  const dates: { date: string; resourceType: string; id: string }[] = [];

  for (const entry of data.entry) {
    if (entry.resource?.effectiveDateTime) {
      dates.push({
        date: entry.resource.effectiveDateTime,
        resourceType: entry.resource.resourceType,
        id: entry.resource.id
      });
    }

    // Check for other date fields
    if (entry.resource?.onsetDateTime) {
      dates.push({
        date: entry.resource.onsetDateTime,
        resourceType: entry.resource.resourceType + '_onset',
        id: entry.resource.id
      });
    }

    if (entry.resource?.period?.start) {
      dates.push({
        date: entry.resource.period.start,
        resourceType: entry.resource.resourceType + '_period_start',
        id: entry.resource.id
      });
    }
  }

  // Sort dates
  dates.sort((a, b) => a.date.localeCompare(b.date));

  console.log('📅 Date Range Analysis:');
  console.log(`   Total dates found: ${dates.length}`);
  console.log(`   Date range: ${dates[0]?.date} to ${dates[dates.length - 1]?.date}`);
  console.log('');

  // Calculate birth date as reference
  const birthDate = new Date(patientEntry.resource.birthDate);
  const birthYear = birthDate.getFullYear();

  console.log('⚠️  Dates Before Birth:');
  const beforeBirth = dates.filter(d => new Date(d.date) < birthDate);
  console.log(`   Found ${beforeBirth.length} dates before birth date`);

  if (beforeBirth.length > 0) {
    console.log('   Examples:');
    for (const item of beforeBirth.slice(0, 10)) {
      const yearDiff = birthYear - new Date(item.date).getFullYear();
      console.log(`     ${item.date} (${yearDiff} years before birth) - ${item.resourceType}`);
    }
  }
  console.log('');

  // Check for extremely old dates
  console.log('🕰️  Extremely Old Dates (before 1950):');
  const oldDates = dates.filter(d => new Date(d.date).getFullYear() < 1950);
  console.log(`   Found ${oldDates.length} dates before 1950`);

  if (oldDates.length > 0) {
    console.log('   Examples:');
    for (const item of oldDates.slice(0, 10)) {
      console.log(`     ${item.date} - ${item.resourceType}`);
    }
  }
  console.log('');

  // Check for future dates
  console.log('🔮 Future Dates (after 2024):');
  const currentYear = new Date().getFullYear();
  const futureDates = dates.filter(d => new Date(d.date).getFullYear() > currentYear);
  console.log(`   Found ${futureDates.length} dates after ${currentYear}`);

  if (futureDates.length > 0) {
    console.log('   Examples:');
    for (const item of futureDates.slice(0, 10)) {
      console.log(`     ${item.date} - ${item.resourceType}`);
    }
  }
  console.log('');

  // Year distribution
  console.log('📊 Year Distribution:');
  const yearCounts: Record<string, number> = {};
  for (const item of dates) {
    const year = new Date(item.date).getFullYear().toString();
    yearCounts[year] = (yearCounts[year] || 0) + 1;
  }

  const sortedYears = Object.entries(yearCounts).sort(([a], [b]) => parseInt(a) - parseInt(b));

  console.log('   First 10 years:');
  for (const [year, count] of sortedYears.slice(0, 10)) {
    console.log(`     ${year}: ${count} records`);
  }

  console.log('   Last 10 years:');
  for (const [year, count] of sortedYears.slice(-10)) {
    console.log(`     ${year}: ${count} records`);
  }

  console.log('\n✅ Date anomaly investigation complete!');
}

if (import.meta.main) {
  investigateDateAnomaly();
}
